draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw book
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.rect(W/2-50, H/2-50, 100, 100);
  ctx.stroke();

  // Draw stick figure
  ctx.beginPath();
  ctx.arc(W/2, H/2-150, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-130);
  ctx.lineTo(W/2, H/2-80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-100);
  ctx.lineTo(W/2-30, H/2-70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-100);
  ctx.lineTo(W/2+30, H/2-70);
  ctx.stroke();

  // Draw wisdom quote
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Apply wisdom', W/2, H/2+50);

  // Animate book opening
  ctx.save();
  ctx.translate(W/2, H/2-50);
  ctx.rotate(Math.sin(t)*0.1);
  ctx.beginPath();
  ctx.rect(-45, -45, 90, 10);
  ctx.stroke();
  ctx.restore();

  // Animate stick figure nodding
  ctx.beginPath();
  ctx.arc(W/2, H/2-150+Math.sin(t)*10, 20, 0, 2*Math.PI);
  ctx.stroke();

  ctx.restore();
}
